UPDATE table_requests
table_id = #{tableId}, request_type = #{requestType}, service_type = #{serviceType,jdbcType=VARCHAR}, note = #{note,jdbcType=VARCHAR}, status = #{status}, completed_at = #{completedAt,jdbcType=TIMESTAMP}, completed_by = #{completedBy,jdbcType=BIGINT},
WHERE id = #{id}

UPDATE table_requests
SET status = 'COMPLETED',
    completed_by = #{completedBy},
    completed_at = #{completedAt}
WHERE table_id = #{tableId}
  AND status = 'PENDING'
